WITH lines AS (SELECT id, host, log_ts, status_code, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, attr_value), gaps AS (SELECT *, CASE WHEN LAG(log_ts) OVER (PARTITION BY host ORDER BY log_ts, id, k) IS NULL OR log_ts > LAG(log_ts) OVER (PARTITION BY host ORDER BY log_ts, id, k) + INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM lines), sessions_app_logs AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps), gaps_2 AS (SELECT *, CASE WHEN LAG(log_ts) OVER (PARTITION BY k ORDER BY log_ts, id, k) IS NULL OR log_ts > LAG(log_ts) OVER (PARTITION BY k ORDER BY log_ts, id, k) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM sessions_app_logs), islands AS (SELECT id, host, log_ts, k, session_start_flag, session_no, SUM(is_new_burst) OVER (PARTITION BY k ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no_2 FROM gaps_2), with_windows AS (SELECT *, SUM(session_no_2) OVER w_hist running_sum_session_no_2, COUNT(session_no_2) OVER w_hist running_count_session_no_2, MIN(session_no_2) OVER w_hist running_min_session_no_2, MAX(session_no_2) OVER w_hist running_max_session_no_2 FROM islands WHERE session_start_flag != 1 WINDOW w_hist AS (PARTITION BY k, host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows_app_logs AS (SELECT id, k, session_start_flag, running_sum_session_no_2, running_count_session_no_2, AVG(running_count_session_no_2) OVER (PARTITION BY k, host ORDER BY running_count_session_no_2, id, k ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) running_count_session_no_2_avg_2_prior, SUM(session_no_2) OVER (PARTITION BY k ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_session_no_2, LAST_VALUE(running_sum_session_no_2) IGNORE NULLS OVER (ORDER BY running_max_session_no_2, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_running_sum_session_no_2, COUNT(session_start_flag) OVER w_running session_start_flag_count_1h, ROW_NUMBER() OVER (PARTITION BY host ORDER BY log_ts DESC, id, k) seq_no FROM with_windows WINDOW w_running AS (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW)), latest AS (SELECT * FROM with_windows_app_logs QUALIFY ROW_NUMBER() OVER (PARTITION BY k ORDER BY session_start_flag, id, k) = 1), metrics AS (SELECT *, LEAD(running_count_session_no_2_avg_2_prior) OVER (PARTITION BY k ORDER BY cumulative_session_no_2, id, k) next_running_count_session_no_2_avg_2_prior, LAG(session_start_flag) OVER (PARTITION BY k ORDER BY cumulative_session_no_2, id, k) prev_session_start_flag, LEAD(session_start_flag) OVER (PARTITION BY k ORDER BY cumulative_session_no_2, id, k) next_session_start_flag, ROW_NUMBER() OVER (PARTITION BY k ORDER BY cumulative_session_no_2, id, k) event_seq FROM latest) SELECT CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS session_start_flag_tier, seq_no, PERCENTILE_APPROX(event_seq, 0.9) AS event_seq_p90, MAX(event_seq) FILTER (WHERE k = 'version') AS version_max_event_seq, COUNT(DISTINCT k) AS distinct_ks, GROUPING_ID() AS grouping_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END, seq_no), (CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY distinct_ks NULLS LAST;
